package com.morphlabs.morph.core.academy.deck

import com.morphlabs.morph.core.academy.Action
import com.morphlabs.morph.core.academy.Card
import com.morphlabs.morph.core.academy.Signal
import com.morphlabs.morph.core.academy.Track

internal object MindCards {
    private val T = Track.MIND
    val cards: List<Card> = listOf(
        // ---- Level 1 · Rookie (adds to the 5 starter cards) -----------------------------------
        concept("mg-present-bias", T, 1, "What is present bias?",
            "Giving today far more weight than tomorrow. It's why Fuliza now feels fine and the fee later feels unreal, and why \"I'll start saving next month\" keeps moving.",
            signals = setOf(Signal.FULIZA_RECENT)),
        quiz("mg-loss-aversion", T, 1, "Losing Ksh 1,000 vs finding Ksh 1,000. For most people, how do they compare?",
            listOf("The loss hurts about twice as much", "They feel the same", "The gain feels twice as strong", "Neither is felt much"), 0,
            "Loss aversion: losses loom larger than equal gains. It makes us cling to bad bets and fear good changes.",
            source = "Kahneman & Tversky, 1979"),
        quiz("mg-anchoring", T, 1, "A shop tags shoes \"Was Ksh 6,000, now Ksh 3,500!\" Which bias is the 6,000 playing on?",
            listOf("Anchoring", "Loss aversion", "Sunk cost", "Hot-hand fallacy"), 0,
            "The first number you see becomes an anchor, so 3,500 feels cheap. Ask instead: would I pay 3,500 if I'd never seen 6,000?",
            source = "Tversky & Kahneman, 1974"),
        quiz("mg-framing-daily", T, 1, "\"Only Ksh 50 a day!\" sounds small. Over a year it is…",
            listOf("Ksh 18,250", "Ksh 1,500", "Ksh 5,000", "Ksh 50,000"), 0,
            "50 × 365 = 18,250. Framing a cost per day makes it feel tiny. Always reframe to the yearly or total price before you agree."),
        quiz("mg-mental-accounting", T, 1, "You treat a Ksh 5,000 bonus as \"free money\" and blow it, but guard salary carefully. This is…",
            listOf("Mental accounting", "Anchoring", "Compound interest", "The endowment effect"), 0,
            "We sort money into mental jars and treat some as less real. But a shilling is a shilling: bonus money buys the same as salary money.",
            source = "Thaler, 1999", signals = setOf(Signal.MONEY_IN_RECENT)),
        concept("mg-wait-rule", T, 1, "What's a simple rule against impulse buys?",
            "Wait 24–48 hours before any want over a set amount, say Ksh 2,000. If you still want it after the urge fades, buy it guilt-free. Many urges just pass.",
            tryThis = "Pick your own \"wait a day\" amount and write it down.", signals = setOf(Signal.BIG_SPEND)),
        concept("mg-payday", T, 1, "Why does money seem to vanish in the first week after payday?",
            "A full balance feels like plenty, so small yeses pile up. Moving savings and bills out on payday leaves a balance that tells the truth about what you can spend.",
            tryThis = "Let Auto-sort split your next income into envelopes.", action = Action.AUTOSORT, signals = setOf(Signal.MONEY_IN_RECENT)),

        // ---- Level 2 · Hustler ----------------------------------------------------------------
        quiz("mg-wait-month", T, 2, "Ksh 1,000 today or Ksh 1,100 in one month. Waiting earns a yearly return of about…",
            listOf("Over 200%", "10%", "About 20%", "About 120%"), 0,
            "10% a month compounds to 1.1¹² − 1 ≈ 214% a year. Yet many people grab the 1,000. That's present bias putting a price on impatience."),
        quiz("mg-preference-reversal", T, 2, "Many pick Ksh 100 today over 110 tomorrow, but 110 in 31 days over 100 in 30 days. Why?",
            listOf("We discount the near future far more steeply", "They can't do maths", "Interest rates changed", "It's the endowment effect"), 0,
            "Hyperbolic discounting: \"now\" gets special weight, so choices flip as a date gets closer. Plans made calmly in advance are usually better plans.",
            source = "Thaler, 1981; Laibson, 1997"),
        quiz("mg-pain-of-paying", T, 2, "MIT students bid on Celtics tickets with cash or a credit card. Card bidders bid…",
            listOf("Nearly twice as much", "About the same", "About 10% more", "Less, fearing debt"), 0,
            "Paying without handing over cash hurts less, so we spend more. Tap-and-go and M-Pesa can do the same. Watching your balance brings the pain back.",
            source = "Prelec & Simester, 2001"),
        quiz("mg-fungibility", T, 2, "You keep Ksh 40,000 \"school fees money\" at 8% while paying a 30% loan. What's the mental-accounting cost?",
            listOf("About 22% a year on 40,000, roughly Ksh 8,800", "Nothing, the jars are separate", "8% a year", "30% of 8%"), 0,
            "Clearing the loan and saving back into the fees jar would gain about 22 points. Labels help discipline, but check they aren't costing you.",
            signals = setOf(Signal.HAS_DEBT)),
        quiz("mg-decoy", T, 2, "Popcorn: small Ksh 150, medium 280, large 300. Why is the medium there?",
            listOf("To make the large look like a bargain", "For people who are medium hungry", "To clear old stock", "It's the most popular"), 0,
            "A decoy option nobody really wants makes the target look great by comparison. Compare each option to your need, not to the other options."),
        concept("mg-framing-gain-loss", T, 2, "Why do \"avoid a Ksh 500 late fee\" and \"get a Ksh 500 early-payment discount\" feel different?",
            "Same money, different frame. Avoiding a loss usually moves us more than chasing an equal gain, so sellers and lenders choose the frame that gets the reaction they want.",
            source = "Tversky & Kahneman, 1981"),
        concept("mg-keeping-up", T, 2, "What is \"keeping up with the Kamaus\" really costing you?",
            "Spending to match friends' visible lives: phones, outings, Instagram trips. You see their spending, never their debts. Your goals, not their feed, should set your budget.",
            tryThis = "Check your Friends & social spending in Patterns.", action = Action.PATTERNS, signals = setOf(Signal.OVER_BUDGET)),
        quiz("mg-urgency", T, 2, "\"Only 2 left! Offer ends tonight!\" What is this designed to do?",
            listOf("Cut your thinking time so you decide on emotion", "Inform you about stock", "Help you save money", "Reward loyal customers"), 0,
            "Scarcity and deadlines trigger fear of missing out. Real bargains rarely vanish forever. Same rule applies to \"investment\" pitches, which is a scam sign.",
            signals = setOf(Signal.BIG_SPEND)),
        concept("mg-availability", T, 2, "Why do jackpot winners on TV make winning feel likely?",
            "The availability heuristic: we judge odds by how easily examples come to mind. You see every winner and none of the millions of losers.",
            source = "Tversky & Kahneman, 1973"),
        concept("mg-commitment", T, 2, "What's a commitment device, and what Kenyan ones do you already know?",
            "A choice that locks your future self in: a chama contribution day, a locked savings account, a SACCO standing order. They work because breaking them costs effort or face.",
            tryThis = "Set one savings move that happens without you deciding.", action = Action.AUTOSORT),
        quiz("mg-default", T, 2, "Why is setting a default so powerful?",
            listOf("Most people stick with whatever happens if they do nothing", "Defaults are legally binding", "Defaults pay higher interest", "People love paperwork"), 0,
            "Inertia is strong. Make saving the default (automatic) and spending the thing that takes effort, and your behaviour follows."),
        quiz("mg-instalment-frame", T, 2, "A phone costs Ksh 20,000 cash, or \"just Ksh 70 a day\" for a year. How much extra does the daily plan cost?",
            listOf("About Ksh 5,550 (about 28% more)", "Nothing extra", "About Ksh 700", "About Ksh 20,000"), 0,
            "70 × 365 = 25,550. The small daily number hides the total. Always compare the full price to the cash price before signing.",
            signals = setOf(Signal.BIG_SPEND)),
        concept("mg-status-quo", T, 2, "Why do people keep paying for a gym or subscription they never use?",
            "Status quo bias: sticking with the current option feels safe and switching takes effort. Samuelson & Zeckhauser (1988) showed people favour whatever is already in place.",
            source = "Samuelson & Zeckhauser, 1988", tryThis = "Find one recurring payment in Patterns you'd not sign up for today.", action = Action.PATTERNS),

        // ---- Level 3 · Pro --------------------------------------------------------------------
        quiz("mg-implied-prob", T, 3, "A team's betting odds are 2.50. What chance of winning does the bookmaker imply?",
            listOf("40%", "25%", "50%", "60%"), 0,
            "Implied probability = 1 ÷ decimal odds = 1 ÷ 2.5 = 40%. If you don't think it's really above 40%, the bet is bad value.",
            source = "Decimal odds maths"),
        quiz("mg-overround", T, 3, "Both sides of a 50/50 match are priced at 1.90. What does that tell you?",
            listOf("The book adds up to 105%; the bookie keeps the extra", "It's a fair bet", "You have an edge", "The bookie expects a draw"), 0,
            "1 ÷ 1.9 = 52.6% each, totalling 105.3%. That extra over 100% (the overround) is the house's built-in margin.",
            source = "Decimal odds maths"),
        quiz("mg-ev-bet", T, 3, "Ksh 100 on a true 50/50 at odds 1.90. Your expected result per bet?",
            listOf("Lose Ksh 5", "Win Ksh 90", "Break even", "Lose Ksh 50"), 0,
            "EV = 0.5 × 190 − 100 = −5. Bet 1,000 times and you expect to lose about Ksh 5,000. The house edge always wins in the long run."),
        quiz("mg-1x2-margin", T, 3, "Home 2.10, Draw 3.20, Away 3.40. The implied chances add up to about…",
            listOf("108%", "100%", "92%", "125%"), 0,
            "47.6% + 31.3% + 29.4% ≈ 108.3%. On a balanced book that's about 7.6% of all stakes kept by the house, no matter who wins."),
        quiz("mg-multibet", T, 3, "Each leg of a 10-game multibet has a 5% house margin. Roughly what share of value do you keep?",
            listOf("About 60%", "About 95%", "About 50%", "About 90%"), 0,
            "Margins multiply: 0.95¹⁰ ≈ 0.60. A big multibet payout hides an expected loss of about 40% of your stake.",
            source = "Decimal odds maths"),
        quiz("mg-jackpot", T, 3, "Guessing a 17-match jackpot (home/draw/away) at random. Your chance of getting all 17?",
            listOf("About 1 in 129 million", "About 1 in 17,000", "About 1 in 1 million", "About 1 in 51"), 0,
            "3¹⁷ = 129,140,163 combinations. Knowing football helps a bit, but not enough to change the picture much."),
        concept("mg-betting-kenya", T, 3, "How common is betting among young Kenyans?",
            "Very. A 2017 GeoPoll survey of youth in six African countries found Kenya highest, with 76% saying they had bet, mostly on football. Later GeoPoll surveys found similar shares.",
            source = "GeoPoll, 2017", timeSensitive = true),
        quiz("mg-gamblers-fallacy", T, 3, "A roulette wheel lands red 6 times in a row. Next spin, black is…",
            listOf("No more likely than before", "Due, so more likely", "Less likely, red is hot", "Certain"), 0,
            "The gambler's fallacy: independent events have no memory. Each spin's odds are unchanged by the last six."),
        concept("mg-chasing", T, 3, "Why do people who are down at betting raise their stakes?",
            "The break-even effect: when behind, people take bigger risks for a chance to get back to zero. Loss-chasing turns a small loss into a big one.",
            source = "Thaler & Johnson, 1990"),
        quiz("mg-house-money", T, 3, "After a big win, a bettor stakes much more freely. This is called…",
            listOf("The house money effect", "The endowment effect", "Anchoring", "Mental budgeting"), 0,
            "Winnings feel like \"the house's money\", not yours, so they get risked more easily. Once paid out, it's your money like any other.",
            source = "Thaler & Johnson, 1990"),
        concept("mg-near-miss", T, 3, "Why do near-misses (\"just one game away!\") keep people betting?",
            "Brain scans show near-misses activate reward areas almost like wins, even though a near-miss is simply a loss. It feels like skill is close.",
            source = "Clark et al., 2009, Neuron"),
        quiz("mg-sunk-car", T, 3, "You spent Ksh 80,000 fixing an old car. Next repair: Ksh 60,000, and it's still unreliable. What should drive the choice?",
            listOf("Only the future costs and benefits", "The 80,000 already spent", "How much you love the car", "What friends paid for theirs"), 0,
            "The 80,000 is gone either way. Compare the next 60,000 (and future repairs) against selling and replacing. Past spending is the sunk-cost trap."),
        quiz("mg-endowment", T, 3, "In a famous experiment, people given a mug asked about how much to sell it, versus what buyers would pay?",
            listOf("Roughly twice as much", "About the same", "Half as much", "Ten times as much"), 0,
            "The endowment effect: owning something makes us value it more. It explains overpriced shamba asks and holding on to shares you'd never buy today.",
            source = "Kahneman, Knetsch & Thaler, 1990"),

        // ---- Level 4 · Shark ------------------------------------------------------------------
        concept("mg-prospect-theory", T, 4, "What are the core ideas of prospect theory (Kahneman & Tversky, 1979)?",
            "We judge outcomes as gains or losses from a reference point, not as final wealth; losses hurt more than gains; sensitivity shrinks as amounts grow; and small chances get overweighted.",
            source = "Kahneman & Tversky, 1979, Econometrica"),
        quiz("mg-lambda", T, 4, "Tversky & Kahneman (1992) estimated the loss aversion coefficient at about…",
            listOf("2.25", "1.0", "0.5", "10"), 0,
            "A loss counts about 2.25 times as much as an equal gain. Estimates vary across later studies, but losses reliably weigh more.",
            source = "Tversky & Kahneman, 1992"),
        quiz("mg-reflection", T, 4, "Prospect theory's reflection effect says people tend to be…",
            listOf("Risk-averse for gains, risk-seeking for losses", "Risk-seeking always", "Risk-averse always", "Neutral to risk"), 0,
            "We lock in sure gains but gamble to avoid a sure loss. That's why traders sell winners too early and hold losers too long.",
            source = "Kahneman & Tversky, 1979"),
        quiz("mg-lottery-insurance", T, 4, "Why might the same person buy both a lottery ticket and insurance?",
            listOf("Both overweight small probabilities", "Both have positive expected value", "Insurance is a lottery", "It's irrational to do either"), 0,
            "Prospect theory: tiny chances (a jackpot, a house fire) feel bigger than they are. Insurance can still be wise, as it protects against ruin."),
        concept("mg-disposition", T, 4, "What is the disposition effect?",
            "Investors sell winning shares too soon and hold losers too long, to avoid admitting a loss. Odean (1998) found the winners they sold went on to beat the losers they kept.",
            source = "Shefrin & Statman, 1985; Odean, 1998"),
        concept("mg-nudge", T, 4, "What is a nudge?",
            "A change in how choices are presented that shifts behaviour without banning anything or changing prices much: defaults, reminders, ordering, simple forms. Coined by Thaler & Sunstein (2008).",
            source = "Thaler & Sunstein, 2008"),
        quiz("mg-auto-enrol", T, 4, "When a US firm made pension saving automatic (opt-out), new hires' participation went from under 40% to about…",
            listOf("85%", "45%", "60%", "100%"), 0,
            "Same people, same plan; only the default changed. Madrian & Shea (2001) made defaults a core policy tool.",
            source = "Madrian & Shea, 2001"),
        quiz("mg-smart", T, 4, "In Save More Tomorrow, workers pre-committed to save more from future raises. Average saving went from 3.5% to…",
            listOf("13.6% in about 40 months", "5% in 5 years", "35% in 1 year", "4% in 40 months"), 0,
            "It beats present bias (the cost is in the future), loss aversion (take-home pay never falls) and inertia (it stays on).",
            source = "Thaler & Benartzi, 2004",
            tryThis = "Decide now what share of your next raise goes to savings."),
        concept("mg-scarcity-tunnel", T, 4, "What do Mullainathan & Shafir mean by \"tunnelling\" in Scarcity (2013)?",
            "When short of money or time, attention narrows to the urgent problem. You solve today, but miss what's outside the tunnel, like the cost of a quick loan.",
            source = "Mullainathan & Shafir, 2013", signals = setOf(Signal.FULIZA_RECENT)),
        quiz("mg-farmers", T, 4, "Indian sugarcane farmers took cognitive tests before and after harvest. They scored better…",
            listOf("After harvest, when they had money", "Before harvest", "The same both times", "Only if well-fed"), 0,
            "Same people, different money situation. Money worries tax mental bandwidth; the authors ruled out nutrition and work effort as the cause.",
            source = "Mani et al., 2013, Science"),
        quiz("mg-money-scripts", T, 4, "Which of Klontz's four money scripts is linked to healthier finances?",
            listOf("Money vigilance", "Money avoidance", "Money worship", "Money status"), 0,
            "Vigilance (careful, saving, discreet) tends to protect. Avoidance (\"money is bad\"), worship (\"more will fix it\") and status (\"net worth = self-worth\") link to worse outcomes.",
            source = "Klontz et al., 2011"),
        concept("mg-hedonic", T, 4, "What is hedonic adaptation?",
            "We get used to good things fast. The new car or bigger house thrills, then becomes normal, so we want the next upgrade. A classic study found lottery winners weren't much happier than others.",
            source = "Brickman et al., 1978"),
        concept("mg-buy-happiness", T, 4, "What spending reliably makes people happier?",
            "Spending on others (Dunn, Aknin & Norton, 2008) and buying back time, like paying to skip chores (Whillans et al., 2017). Experiences tend to beat things over time.",
            source = "Dunn et al., 2008; Whillans et al., 2017"),

        // ---- Level 5 · Legend -----------------------------------------------------------------
        quiz("mg-kahneman-deaton", T, 5, "Kahneman & Deaton (2010) found US day-to-day emotional well-being stopped rising above about…",
            listOf("US\$75,000 a year", "US\$20,000 a year", "US\$250,000 a year", "It never stopped rising"), 0,
            "Life evaluation (how you rate your life) kept rising with income, but daily mood seemed to plateau. The plateau became famous, and contested.",
            source = "Kahneman & Deaton, 2010, PNAS"),
        quiz("mg-killingsworth", T, 5, "Killingsworth (2021) used over a million real-time phone reports. He found well-being…",
            listOf("Kept rising with income, no plateau", "Plateaued at US\$75,000", "Fell at high incomes", "Was unrelated to income"), 0,
            "Happiness rose with log income, as steeply above US\$80,000 as below it. That clashed directly with Kahneman & Deaton.",
            source = "Killingsworth, 2021, PNAS"),
        concept("mg-adversarial", T, 5, "How did the 2023 adversarial collaboration settle the income-happiness fight?",
            "Killingsworth, Kahneman and Mellers re-analysed the data together. For most people happiness keeps rising with income. Only the least happy group (about 20%) plateaus, around US\$100,000.",
            source = "Killingsworth, Kahneman & Mellers, 2023, PNAS"),
        concept("mg-log-income", T, 5, "Happiness tracks the log of income. What does that mean in practice?",
            "Each doubling adds about the same happiness. Going from Ksh 20k to 40k a month matters about as much as from 200k to 400k. So extra money matters most where there's least of it."),
        quiz("mg-marshmallow", T, 5, "Watts, Duncan & Quan (2018) redid the marshmallow test with about 900 children. The link to teen achievement was…",
            listOf("About half as big, and shrank by 2/3 with family controls", "Twice as big as the original", "Exactly as in the original", "Negative"), 0,
            "Family background and early ability explained much of it. Delay at age 4 predicted far less about later life than the famous story claimed.",
            source = "Watts, Duncan & Quan, 2018"),
        concept("mg-rational-snacking", T, 5, "Why might a child rationally eat the marshmallow early?",
            "If promises usually aren't kept. Kidd et al. (2013) found children who'd just seen an adult break a promise waited about 3 minutes, versus about 12 after a kept promise. Trust shapes patience.",
            source = "Kidd, Palmeri & Aslin, 2013"),
        quiz("mg-barber-odean", T, 5, "Barber & Odean studied 66,465 households (1991–96). The most active traders earned about 11.4% a year vs the market's…",
            listOf("17.9%", "11.4%", "8%", "25%"), 0,
            "Trading costs and bad timing ate their returns. The paper's title says it all: \"Trading Is Hazardous to Your Wealth.\"",
            source = "Barber & Odean, 2000, J. of Finance"),
        quiz("mg-boys-trade", T, 5, "In Barber & Odean's \"Boys Will Be Boys\" (2001), men traded how much more than women?",
            listOf("About 45% more", "About the same", "About 5% more", "Women traded more"), 0,
            "Overconfidence drove the extra trading, which cut men's net returns by about 2.65 points a year versus 1.72 for women.",
            source = "Barber & Odean, 2001"),
        quiz("mg-better-than-average", T, 5, "In Svenson's 1981 study, what share of US drivers rated themselves safer than the median driver?",
            listOf("About 88%", "About 50%", "About 25%", "About 65%"), 0,
            "Mathematically only half can be above the median. Overconfidence is why we trade too much and think our hustle can't fail.",
            source = "Svenson, 1981"),
        quiz("mg-dalbar", T, 5, "DALBAR estimates the average US equity fund investor trailed the S&P 500 by 8.5 points in 2024. In 2025 the gap was…",
            listOf("About 0.7 points", "About 8.5 points again", "About 20 points", "Investors beat the index by 5"), 0,
            "The \"behavior gap\" from buying high and selling low swings a lot year to year. Critics also question DALBAR's method, so treat single figures with care.",
            source = "DALBAR QAIB, 2026", timeSensitive = true),
        concept("mg-hot-hand", T, 5, "Is the basketball \"hot hand\" a fallacy after all?",
            "Gilovich, Vallone & Tversky (1985) said yes. Miller & Sanjurjo (2018) found a subtle bias in that method; corrected, there's evidence of a modest hot hand. Good scientists revise.",
            source = "Miller & Sanjurjo, 2018, Econometrica"),
        quiz("mg-premium-gas", T, 5, "When US petrol prices fell in 2008, families bought premium fuel far more than extra income predicted. Why?",
            listOf("Mental accounting: savings stayed in the \"fuel\" jar", "Premium got cheaper than regular", "Cars needed it", "Inflation"), 0,
            "Hastings & Shapiro (2013) found the savings were spent on fuel upgrades, as if money in the fuel budget couldn't leave it. A real-world test of fungibility.",
            source = "Hastings & Shapiro, 2013"),
        concept("mg-ego-depletion", T, 5, "Is willpower a tank that runs out (\"ego depletion\")?",
            "A 23-lab replication (Hagger et al., 2016) found an effect close to zero. Don't rely on willpower either way: design defaults so you rarely need it.",
            source = "Hagger et al., 2016"),
    )
}
